package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("సుబ్బహున్ కుద్దుస్ (రుకు & సుజూద్)", "(అల్లాహ్) అత్యంత మహిమపరచబడ్డాడు, అత్యంత పవిత్రుడు, దేవతలకు మరియు ఆత్మకు ప్రభువు (జిబ్రిల్).", "రుకు మరియు సుజూద్ లో.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని రుకు మరియు సుజూద్ భాషలలో పఠించారు."),
        "dua_sujood_dhanbi_kullah" to DuaText("సుజూద్ లోః నా పాపాలన్నింటినీ క్షమించండి", "ఓ అల్లాహ్, నా పాపాలన్నింటినీ క్షమించండి-చిన్నవి మరియు పెద్దవి, మొదటివి మరియు చివరివి, బహిరంగమైనవి మరియు రహస్యమైనవి.", "సుజూద్ లో.", "ప్రోస్ట్రేషన్ అనేది దుఆలకు సమాధానం ఇచ్చే ప్రదేశం."),
        "dua_sujood_ridaka" to DuaText("మీ ఆనందంలో ఆశ్రయం", "ఓ అల్లాహ్, నేను నీ కోపం నుండి నీ సంతోషంలో, నీ శిక్ష నుండి నీ క్షమాపణలో ఆశ్రయం పొందుతున్నాను, మరియు నేను నీ నుండి నిన్ను ఆశ్రయిస్తున్నాను. నేను నిన్ను పూర్తిగా స్తుతించలేను. నీవు నిన్ను తాను స్తుతించుకున్నట్లే ఉన్నావు.", "సుజూద్ లో-ఆయిషా (ర) ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ మాట చెప్పడం విన్నారు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క సుజూద్ దుఆ."),
        "dua_tashahhud" to DuaText("తాషాహుద్ (అట్-తహియాత్)", "అన్ని మౌఖిక, శారీరక, ఆర్థిక ఆరాధనలు అల్లాహ్కే చెందుతాయి. ప్రవక్త గారూ, మీపై శాంతి, అల్లాహ్ కరుణ, ఆయన ఆశీర్వాదాలు ఉండుగాక. మాకు, అల్లాహ్ యొక్క ధర్మనిష్ఠగల సేవకులకు శాంతి కలుగుగాక. అల్లాహ్ తప్ప మరెవరికీ ఆరాధించబడే హక్కు లేదని నేను సాక్ష్యమిస్తున్నాను, ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం ఆయన సేవకుడు, ప్రవక్త అని నేను సాక్ష్యమిస్తున్నాను.", "ప్రతి సమావేశంలో-అబ్దుల్లా ఇబ్న్ మసూద్ (ర) (హనాఫీ ఆచారం) వివరించాడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని ఖురాన్ యొక్క సూరాహ్ లాగా బోధించారు."),
        "dua_sajdah_tilawah" to DuaText("పఠణ యొక్క సజ్దాహ్", "దానిని సృష్టించి, తన శక్తి మరియు శక్తితో దాని వినికిడి మరియు దృష్టిని తీసుకువచ్చిన వ్యక్తికి నా ముఖం సాష్టాంగ నమస్కారం చేసింది.", "పారాయణంలో సాష్టాంగ నమస్కారం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం రాత్రి పూట సాష్టాంగ నమస్కారం చేస్తూ ఈ విషయం చెప్పారు."),
        "dua_after_witr" to DuaText("విటర్ తర్వాత", "అత్యంత పవిత్రుడైన రాజుకు మహిమ కలగాలి.", "విత్ర్ సలాం తర్వాత మూడు సార్లు, మూడవసారి స్వరం పెంచండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ విషయం విదర్ తరువాత చెప్పారు."),
        "dua_tahajjud_nur" to DuaText("తహజ్జూద్ ప్రారంభ ప్రార్థన", "అల్లాహ్వే, స్తుతులు నీకు చెందినవి, ఆకాశాలు, భూమి మరియు వాటిలో ఉన్న అన్నిటికీ నీవే పరిపాలకుడు. స్తుతులు నీకు చెందినవి. నీవు ఆకాశాలకు, భూమికి మరియు వాటిలో ఉన్న అన్నిటికీ వెలుగు. ప్రశంసలు నీకు చెందినవి. నీవే సత్యం, నీ వాగ్దానం నిజం, నీతో కలవడం నిజం, నీ మాట నిజం, స్వర్గం నిజం, నరకం నిజం, ప్రవక్తలు నిజం, ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం నిజం మరియు గంట నిజం.", "రాత్రి ప్రార్థన (తహజ్జుద) (దుఆ ప్రారంభ భాగం) ప్రారంభించేటప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వస్లం తహజ్జుద్కు ఎదిగినప్పుడు (పూర్తి దుఆ అల్-బుఖారీలో ఉంది) దీనిని పఠించారు."),
        "dua_rabba_jibrail" to DuaText("వివాదాస్పద విషయాలలో నాకు మార్గనిర్దేశం చేయండి", "అల్లాహ్, జిబ్రిల్, మీకైల్, ఇస్ఱాఫిల్ ల ప్రభువు, ఆకాశాలు, భూమిని సృష్టించినవాడు, అదృశ్యం, దృశ్యాన్ని తెలిసినవాడు! నీ సేవకుల మధ్య వారు విభేదించే విషయాలలో నీవు తీర్పు చెబుతా. విభేదించిన విషయాలలో నీ అనుమతితో నన్ను సత్యానికి నడిపించు. నిశ్చయంగా, నీవు కోరుకున్న వారిని సరళమైన మార్గంలో నడిపించు.", "తహజ్జుద ప్రారంభంలో-అసమ్మతి మధ్య సత్యానికి మార్గనిర్దేశం కోసం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆతో తన రాత్రి ప్రార్థనను ప్రారంభించారు."),
        "dua_going_to_mosque_nur" to DuaText("మసీదుకు వెళ్లడం (వెలుగు యొక్క దువా)", "ఓ అల్లాహ్, నా హృదయంలో కాంతిని, నా కళ్ళలో కాంతిని, నా చెవులలో కాంతిని, నా కుడి వైపున కాంతిని, నా ఎడమ వైపున కాంతిని, నా పైన కాంతిని, నా క్రింద కాంతిని, నా ముందు కాంతిని, నా వెనుక కాంతిని ఉంచండి, నాకు కాంతిని కలిగించండి.", "ఫజ్ కోసం మసీదుకు వెళుతున్నప్పుడు.", "ప్రార్ధన కోసం బయటకు వెళ్ళేటప్పుడు ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని పఠించారు."),
        "dua_waswasa_salah" to DuaText("సలాహ్ సమయంలో వాస్వాసా (ఖిన్జాబ్)", "నేను శపించబడిన షైతాన్ నుండి అల్లాహ్ ఆశ్రయాన్ని కోరుతున్నాను.", "ప్రార్థన సమయంలో సాతాను గుసగుసలు వచ్చినప్పుడు, ఆశ్రయం పొందండి మరియు మూడు సార్లు ఎడమ వైపుకు తేలికగా ఉమ్మివేయండి.", "ఉస్మాన్ ఇబ్న్ అబిల్ -'అస్ (ర) ఇలా చేసాడు మరియు గుసగుసలు వెళ్లిపోయాయి."),
        "dua_alimal_ghayb" to DuaText("కనిపించని విషయం తెలిసినవాడు", "ఓ అల్లాహ్, అదృశ్యమైనవి మరియు కనిపించేవి తెలిసినవాడే, ఆకాశాలను మరియు భూమిని సృష్టించినవాడే, అన్నిటికీ ప్రభువు మరియు సార్వభౌమాధికారి! నీవు తప్ప దేవుడు లేడని నేను సాక్ష్యమిస్తున్నాను. నా స్వంత దుష్టత్వం నుండి, షైతాన్ యొక్క దుష్టత్వం నుండి మరియు అతని షర్క్ నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "ఉదయం, సాయంత్రం మరియు నిద్రపోయే ముందు-ప్రవక్త సల్లల్లాహు అలైహి వసల్లం అబూ బకర్ (ర) కు బోధించారు.", "స్వీయ మరియు శైతాన్ యొక్క చెడు నుండి రక్షణ."),
        "dua_fitratil_islam" to DuaText("ఇస్లాం యొక్క ఫిత్రాపై", "ఇస్లాం యొక్క ఫిత్రాలో, నిజాయితీ మాటపై, మా ప్రవక్త ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం యొక్క మతం మీద మరియు మా తండ్రి ఇబ్రహీం (ఎ. ఎస్) మార్గంలో మేము ఉదయం ప్రవేశించాము, అతను నిటారుగా మరియు ముస్లిం, మరియు బహుదేవతారాధకులలో లేడు.", "ఉదయం వేళ.", "ప్రతి ఉదయం ఒకరి విశ్వాసాన్ని పునరుద్ధరించుకోండి."),
        "dua_amsayna_fitrah" to DuaText("ఇస్లాం యొక్క ఫిత్రాపై సాయంత్రం", "ఇస్లాం యొక్క ఫిత్రాలో సాయంత్రం, నిజాయితీ మాటపై, మా ప్రవక్త ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం యొక్క మతం మీద మరియు మా తండ్రి ఇబ్రహీం (ఎ. ఎస్) మార్గంలో ప్రవేశించాము, అతను నిటారుగా మరియు ముస్లిం, మరియు బహుదేవతారాధకులలో లేడు.", "సాయంత్రం వేళ.", "ప్రతి సాయంత్రం ఒకరి విశ్వాసాన్ని పునరుద్ధరించండి."),
        "dua_tahleel_10_fajr" to DuaText("ఫజ్ర్ మరియు మగ్రిబ్ తరువాత పది తహ్లీల్", "అల్లాహ్ తప్ప, ఎవరినీ పూజించే హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. ఆధిపత్యం మరియు ప్రశంసలు ఆయనదే, అతను జీవం ఇస్తాడు మరియు మరణాన్ని కలిగిస్తాడు, మరియు అతను అన్ని విషయాలపై అధికారం కలిగి ఉంటాడు.", "ఫజ్ర్ (మరియు మగ్రిబ్) తర్వాత పది సార్లు, మీరు కూర్చోవడం లేదా మాట్లాడటం నుండి వెళ్ళే ముందు.", "పది మంచి పనులు, పది పాపాలు చెరిపివేయబడ్డాయి, పది ర్యాంకులను పెంచారు మరియు రోజంతా సైతాన్ నుండి రక్షణ పొందారు."),
        "dua_la_hawla_kanz" to DuaText("ఎ ట్రెజర్ ఆఫ్ జన్నా", "అల్లాహ్ వద్ద తప్ప శక్తి, శక్తి ఏమీ లేవు.", "తరచుగా, అన్ని సమయాల్లో.", "ఇది స్వర్గపు సంపదల్లో ఒకటి."),
        "dua_four_beloved_words" to DuaText("అత్యంత ప్రియమైన నాలుగు పదాలు", "అల్లాహ్ మహిమగలవాడు, అన్ని ప్రశంసలు అల్లాహ్ కోసం, అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడే హక్కు లేదు, మరియు అల్లాహ్ గొప్పవాడు.", "అల్లాహ్కు అత్యంత ప్రియమైన పదాలు.", "అవి సూర్యుడు ఉదయించే ప్రతిదాని కంటే ప్రవక్తకు ప్రియమైనవి."),
        "dua_two_light_words" to DuaText("రెండు పదాలు నాలుక మీద వెలుగు", "మహిమ అల్లాహ్కు, సమస్త స్తుతులు ఆయనకే, మహిమగల అల్లాహ్ కు.", "నాలుకపై తేలికగా, స్కేల్పై భారీగా ఉంటుంది.", "అత్యంత దయగలవారికి ప్రియమైనవారు, నాలుకపై తేలికైనవారు మరియు కొలతపై భారమైనవారు. (అల్-బుఖారీ యొక్క చివరి హదీస్)"),
        "dua_ya_dhal_jalal" to DuaText("యా ధల్-జలాలి వాల్-ఇక్రమ్", "ఓ మహిమ మరియు గౌరవం కలిగిన స్వామీ!", "ప్రవక్త యొక్క సలీం అల్లాహ్ వస్ లమ్ సూచన-దుఆ లో దానిని పట్టుకోండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః'యా ధల్-జలాలీ వాల్-ఇక్రమ్'ను పట్టుకోండి."),
        "dua_sleep_wadatu_janbi" to DuaText("నీ నామంలో నేను పడుకుంటున్నాను", "నా ప్రభూ, నీ నామమునుబట్టి నేను నా పక్షము ఉంచుచున్నాను, నీ నామమునుబట్టి నేను లేచున్నాను. నీవు నా ప్రాణమును తీసికొని దాని మీద కరుణ చూపుము, దానిని విడుదల చేసినయెడల, నీ నీతిమంతులైన సేవకులను రక్షించినట్లే దానిని కాపాడుము.", "మంచం దుమ్ము దులిపిన తరువాత పడుకోండి.", "నిద్రపోయే ముందు తన ఆత్మను అల్లాహ్కు అప్పగించండి."),
        "dua_sleep_khalaqta_nafsi" to DuaText("మీరు నా ఆత్మను సృష్టించారు.", "ఓ అల్లాహ్, నీవు నా ఆత్మను సృష్టించావు, దానిని తీస్కుంటావు. దాని మరణం మరియు దాని జీవితం నీదే. నీవు దానిని సజీవంగా ఉంచుకుంటే, దానిని రక్షించండి, మరియు మీరు దానిని మరణానికి కారణమైతే, దానిని క్షమించండి. ఓ అల్లాహ్, నేను నిన్ను శ్రేయస్సు కోసం అడుగుతున్నాను.", "నిద్రపోయే ముందు-ఇబ్న్ ఉమర్ (ర) వివరించాడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం నిద్రవేళలో ఇలా చెప్పమని ఆదేశించారు."),
        "dua_sleep_atamana" to DuaText("నిద్రపోయే ముందు కృతజ్ఞత", "మాకు తినిపించిన, మాకు పానీయం ఇచ్చిన, మాకు తగినంతగా ఆశ్రయం ఇచ్చిన అల్లాహ్ కోసం అన్ని ప్రశంసలు. వారికి తగినంతగా ఎవరూ లేని లేదా వారికి ఆశ్రయం ఇవ్వని వారు ఎంత మంది ఉన్నారు.", "పడుకున్నప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం పడుకునే సమయంలో ఈ విషయం చెప్పారు."),
        "dua_sleep_rabbas_samawat" to DuaText("స్వర్గపు ప్రభువు-మన రుణాన్ని చెల్లించండి", "ఆకాశాలకు, భూమికి, శక్తివంతమైన సింహాసనానికి, మా ప్రభువైన, అన్నిటికీ ప్రభువైన, విత్తనాలు, ఖర్జూరం, తోరా, ఇంజిల్, ఫుర్కాన్ లను బహిర్గతం చేసే ప్రభువైన, అన్నిటికీ ప్రభువైన అల్లాహ్! మీరు ముందు పట్టుకున్న ప్రతిదాని చెడు నుండి నేను మీలో ఆశ్రయం పొందుతున్నాను. ఓ అల్లాహ్, మీరు మొదటివారు, మీ ముందు ఏమీ లేదు; మీరు చివరివారు, మీ తర్వాత ఏమీ లేదు; మీరు స్పష్టమైనవారు, మీ పైన ఏమీ లేదు, మీరు దాచినవారు, మీ నుండి ఏదీ లేదు. మా రుణాన్ని మాకు పరిష్కరించండి మరియు మాకు పేదరికం నుండి విముక్తి ఇవ్వండి.", "నిద్రపోయే ముందు, కుడి వైపున పడుకోండి-ఫాతిమా (రా) కు నేర్పించండి.", "రుణం మరియు కష్టాల నుండి ఉపశమనం కోసం ఒక దుఆ."),
        "dua_sleep_fear" to DuaText("నిద్రలో భయం లేదా అసౌకర్యం", "అల్లాహ్ యొక్క కోపం మరియు అతని శిక్ష నుండి, అతని సేవకుల చెడు నుండి, దయ్యాల గుసగుసల నుండి మరియు వారు నా వద్దకు రావడం నుండి నేను పరిపూర్ణమైన మాటలకు ఆశ్రయం కోరుతున్నాను.", "నిద్రలో భయం లేదా అసౌకర్యాన్ని అనుభవించినప్పుడు.", "అలా చేయడం వల్ల, ఆ విషయం అతనికి హాని చేయదు."),
        "dua_waking_afani" to DuaText("మేల్కొనడంః ఆయన నా ఆత్మను పునరుద్ధరించాడు", "నా శరీర శ్రేయస్సును ఇచ్చిన, నా ఆత్మను నాకు తిరిగి ఇచ్చి, ఆయనను స్మరించుకోవడానికి అనుమతించిన అల్లాహ్ కు అన్ని ప్రశంసలు.", "మేల్కొనేటప్పుడు.", "కొత్త ఉదయం కోసం కృతజ్ఞతలు."),
        "dua_allahu_rabbi" to DuaText("అల్లాహ్, అల్లాహ్ నా ప్రభువు.", "అల్లాహ్, అల్లాహ్ నా ప్రభువు; నేను అతనితో దేనినీ అనుబంధించను.", "దుఃఖం లేదా బాధలో-ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని ఆస్మా బింట్ ఉమైస్ (రా) కు నేర్పించారు.", "కష్ట సమయాల్లో తౌహీద్ను పట్టుకోండి."),
        "dua_rahmataka_arju" to DuaText("నీ దయను నేను ఆశిస్తున్నాను", "ఓ అల్లాహ్, నేను ఆశిస్తున్నది నీ దయ, కాబట్టి నన్ను ఒక్క కన్ను చిమ్మేంత వరకు కూడా నాకు వదిలివేయకండి, నా వ్యవహారాలన్నింటినీ సరిచేయండి. నీవు తప్ప దేవుడు లేడు.", "బాధలో ఉన్న వ్యక్తి యొక్క దుఆ (దావత్ అల్-మక్రబ్).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని బాధలో ఉన్నవారి దుఆ అని పిలిచారు."),
        "dua_against_enemy_ahzab" to DuaText("శత్రువుల సైన్యాలకు వ్యతిరేకంగా", "ఓ అల్లాహ్, గ్రంథాన్ని వెల్లడి చేసేవాడే! వేగంగా లెక్కించండి! సమాఖ్యలను ఓడించండి. ఓ అల్లాహ్, వారిని ఓడించి, వారిని కదిలించండి.", "శత్రువుకు వ్యతిరేకంగా-కాన్ఫెడరేట్స్ యుద్ధం యొక్క డువా.", "శత్రువుకు వ్యతిరేకంగా ప్రవక్త యొక్క సలీం."),
        "dua_anta_adudi" to DuaText("మీరు నాకు మద్దతుదారు", "ఓ అల్లాహ్, నీవు నాకు మద్దతుదారు, నాకు సహాయకుడు. నీ ద్వారానే నేను ప్రణాళిక వేస్తాను, నీ ద్వారానే నేను ముందుకు సాగుతాను, నీ ద్వారానే నేను పోరాడతాను.", "ఒక పోటీ లేదా పెద్ద సవాలుకు ముందు.", "ఈ విషయాన్ని ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యుద్ధంలో చెప్పారు."),
        "dua_ikfinihim" to DuaText("వారికి వ్యతిరేకంగా నాకు సరిపోతుంది", "ఓ అల్లాహ్, మీరు కోరుకున్నంత వరకు వారికి వ్యతిరేకంగా నాకు సరిపోతుంది.", "అణచివేతదారుల చెడుకు వ్యతిరేకంగా-ది పీపుల్ ఆఫ్ ది డిచ్ కథలో బాలుడి దువా.", "అల్లాహ్ ఆ బాలుడిని అణచివేతదారుల నుండి రక్షించాడు."),
        "dua_qadarullah" to DuaText("ఏదైనా చెడు జరిగినప్పుడు", "ఇది అల్లాహ్ యొక్క ఆజ్ఞ, మరియు అతను తాను కోరుకున్నది చేసాడు.", "ఏదైనా అసహ్యకరమైనది జరిగినప్పుడు,'ఉంటే మాత్రమే'అని చెప్పడానికి బదులుగా.", "'ఉంటే మాత్రమే'షైతాన్కు తలుపులు తెరుస్తుంది."),
        "dua_ala_kulli_hal" to DuaText("ప్రతి పరిస్థితిలోనూ ప్రశంసించండి", "ప్రతి పరిస్థితిలోనూ అల్లాహ్ కు స్తుతి ఉంటుంది.", "ఏదైనా నచ్చనిది జరిగినప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తనకు నచ్చనిదాన్ని ఎదుర్కొన్నప్పుడు ఈ విషయం చెప్పారు."),
        "dua_dogs_barking" to DuaText("రాత్రిపూట వినికిడి కుక్కలు మొరిగుతాయి", "నేను శపించబడిన షైతాన్ నుండి అల్లాహ్ ఆశ్రయాన్ని కోరుతున్నాను.", "కుక్కలు మొరిగే శబ్దం వినగానే లేదా రాత్రి వేళలో గాడిద బ్రెయి చేస్తుంది.", "మీరు చూడని వాటిని వారు చూస్తారు."),
        "dua_leaving_home_adilla" to DuaText("దారి తప్పకుండా శరణార్థులు", "ఓ అల్లాహ్, నేను దారి తప్పకుండా లేదా దారి తప్పకుండా ఉండటానికి, నేను తప్పుదోవ పట్టకుండా లేదా జారిపోయేలా చేయబడకుండా, నేను తప్పు చేయబడకుండా లేదా అన్యాయం చేయబడకుండా, నేను మూర్ఖంగా ప్రవర్తించబడకుండా లేదా మూర్ఖంగా వ్యవహరించబడకుండా ఉండటానికి నేను నీ ఆశ్రయాన్ని కోరుతున్నాను.", "ఇంటి నుండి బయటకు వెళ్ళేటప్పుడు-ఉమ్ సలమా (రా) వివరించాడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తన ఇంటి నుండి బయటకు వచ్చినప్పుడల్లా దీనిని పఠించేవారు."),
        "dua_ascending_descending" to DuaText("పైకి వెళ్లి కిందకి రావడం", "అల్లాహ్ (పైకి వెళ్ళేటప్పుడు) గొప్పవాడు.-మహిమగల అల్లాహ్ (దిగుతున్నప్పుడు).", "ప్రయాణంలో, పైకి వెళ్ళేటప్పుడు'అల్లాహు అక్బర్'అని, కిందికి రాగానే'సుభానల్లాహ్'అని చెప్పండి.", "ప్రయాణించేటప్పుడు సహచరుల (ఆర్ఏ) అభ్యాసం."),
        "dua_traveller_sahar" to DuaText("తెల్లవారుజామున ముందు యాత్రికుల దువా", "ఒక వినేవాడు అల్లాహ్ను స్తుతిస్తూ, ఆయన అనుగ్రహాలు మాపై ఉంటాయని విన్నాడు. మా ప్రభూ, మాతో కలిసి రండి, మాకు నీ అనుగ్రహం ప్రసాదించండి-(నేను ఇలా చెప్తున్నాను) అగ్ని నుండి అల్లాహ్కు ఆశ్రయం కోరుతూ.", "ఒక ప్రయాణంలో, తెల్లవారుజామున ముందు.", "ప్రయాణించేటప్పుడు తెల్లవారుజామున ముందు ప్రవక్త ఈ విషయం చెప్పారు."),
        "dua_zawwadakallah" to DuaText("ప్రయాణికుడికిః అల్లాహ్ తక్వా ప్రసాదించుగాక", "అల్లాహ్ మీ ప్రయాణానికి తక్వాను అందించి, మీ పాపాలను క్షమించి, మీరు ఎక్కడ ఉన్నా మీకు మేలు చేయనివ్వండి.", "ఒక ప్రయాణికుడికి వీడ్కోలు పలుకుతున్నప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ప్రయాణంలో బయలుదేరిన వ్యక్తికి ఈ దుఆ ఇచ్చారు."),
        "dua_traveller_to_resident" to DuaText("వెనుక ఉన్నవారికి ప్రయాణికుడు", "నేను నిన్ను అల్లాహ్కు అప్పగిస్తున్నాను, ఆయనపై ఉన్న నమ్మకాలు ఎప్పటికీ పోవు.", "కుటుంబానికి వీడ్కోలు పలికినప్పుడు యాత్రికుడు ఇలా చెప్పాడు.", "కుటుంబ భద్రతను అల్లాహ్కు అప్పగించడం."),
        "dua_entering_village" to DuaText("ఒక పట్టణం లేదా గ్రామంలోకి ప్రవేశించడం", "ఏడు ఆకాశాలకు, వాటి నీడకు, ఏడు భూములకు, అవి మోసుకెళ్లే అన్నిటికీ, దయ్యాలకు, అవి దారి తప్పించే అన్నిటికీ, గాలి మరియు అవి చెదరగొట్టే అన్నిటికీ, ప్రభువు అయిన అల్లాహ్వే! మేము ఈ పట్టణానికి, దాని ప్రజలకు మేలు కోసం నిన్ను అడుగుతున్నాము, దాని చెడు నుండి, దాని ప్రజల చెడు నుండి, దానిలోని చెడు నుండి మేము నిన్ను ఆశ్రయిస్తున్నాము.", "ఒక పట్టణం లేదా నగరంలోకి ప్రవేశించే ముందు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఒక పట్టణంలోకి ప్రవేశించాలనుకున్నప్పుడల్లా దీనిని పఠించారు."),
        "dua_vehicle_stumbles" to DuaText("వాహనం పడిపోయినప్పుడు", "అల్లాహ్ పేరిట.", "మౌంట్ లేదా వాహనం జారిపోయినప్పుడు లేదా పొరపాట్లు చేసినప్పుడు,'శాయ్తాన్ నశించిపోవచ్చు'అని చెప్పడానికి బదులుగా.", "బిస్మిల్లా అని చెప్పడం వల్ల శైతాన్ ఫ్లై పరిమాణానికి కుదించబడుతుంది."),
        "dua_ajz_kasal_haram" to DuaText("బలహీనత మరియు వృద్ధాప్యం నుండి శరణార్ధులు", "ఓ అల్లాహ్, నిస్సహాయత మరియు సోమరితనం నుండి, పిరికితనం మరియు వృద్ధాప్యం నుండి, జీవితం మరియు మరణం యొక్క పరీక్షల నుండి మరియు సమాధి శిక్ష నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "ఒక సమగ్ర రోజువారీ దుఆ ఆశ్రయం.", "ప్రవక్త తరచుగా చేసే ఒక దుఆ."),
    )
}
